function extractArticle() {
  // Get all paragraphs
  const paragraphs = document.querySelectorAll('p');
  const articleText = Array.from(paragraphs).map(p => p.innerText).filter(t => t.length > 30).join('\n\n');

  // Get all headlines
  const headlines = document.querySelectorAll('h2, h3');
  const subheadings = Array.from(headlines).map(h => h.innerText).filter(t => t.length > 0).join('\n');

  // Get date and author
  const dateEl = document.querySelector('time');
  const date = dateEl ? dateEl.innerText : '';

  return {
    title: document.title,
    date: date,
    articleText: articleText.slice(0, 10000),
    subheadings: subheadings
  };
}
return extractArticle();
